SL.CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
SL.CODE = ['a','Z','8','k','Q','2','f'];

SL.fmt = function(n){
  n = Math.round(n);
  var s = String(n), out = '', c = 0;
  for(var i = s.length - 1; i >= 0; i--){
    out = s.charAt(i) + out; c++;
    if(c % 3 === 0 && i > 0) out = ',' + out;
  }
  return out;
};

SL.ramp = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = SL.fmt(from + (to - from) * p);
    if(p >= 1) clearInterval(id);
  });
};

SL.scene = function(id, whip){
  MSD.cls('.sl-sc', 'on', false);
  MSD.cls('#sl-sc-' + id, 'on', true);
